def _guessunit(self):
        """Guess the unit of the period as the largest one, which results in
        an integer duration.
        """
        if self.duration is None:
            return
        if self.duration.microseconds:
            self.unit = 'us'
        elif self.duration.seconds:
            self.unit = 's'
        elif self.duration.days:
            self.unit = 'd'

